import subprocess

result = subprocess.run(
    ["nm", "--defined-only", "libmonosgen-2.0.so.dbg"],
    capture_output=True, text=True
)

symbols = []
for line in result.stdout.strip().split('\n'):
    parts = line.split()
    if len(parts) >= 3:
        addr = int(parts[0], 16)
        name = parts[2]
        symbols.append((addr, name))

symbols.sort(key=lambda x: x[0])

for pc in [0x2f4b20, 0x2f4c84]:
    best = None
    for addr, name in symbols:
        if addr <= pc:
            best = (addr, name)
        else:
            break
    if best:
        print(f"0x{pc:x} => {best[1]}+0x{pc - best[0]:x} (base 0x{best[0]:x})")
