# $d markers are ARM mapping symbols. Let's find the actual function symbols nearby
python3 << 'PYEOF'
import subprocess

result = subprocess.run(
    ["nm", "--defined-only", "libmonosgen-2.0.so.dbg"],
    capture_output=True, text=True
)

symbols = []
for line in result.stdout.strip().split('\n'):
    parts = line.split()
    if len(parts) >= 3:
        addr = int(parts[0], 16)
        stype = parts[1]
        name = parts[2]
        symbols.append((addr, stype, name))

symbols.sort(key=lambda x: x[0])

# Filter out mapping symbols ($d, $x, etc.)
func_symbols = [(a, t, n) for a, t, n in symbols if not n.startswith('$')]

for pc in [0x2f4b20, 0x2f4c84]:
    best = None
    for addr, stype, name in func_symbols:
        if addr <= pc:
            best = (addr, name)
        else:
            break
    if best:
        print(f"0x{pc:x} => {best[1]}+0x{pc - best[0]:x} (base 0x{best[0]:x})")
PYEOF", "description": "Find real function symbols"}

