import subprocess, re

result = subprocess.run(["readelf", "-S", "libmonosgen-2.0.so.dbg"], capture_output=True, text=True)
for line in result.stdout.split('\n'):
    m = re.search(r'\[\s*\d+\]\s+(\S+)\s+\S+\s+([0-9a-f]+)\s+[0-9a-f]+\s+([0-9a-f]+)', line)
    if m:
        name, addr_str, size_str = m.group(1), int(m.group(2), 16), int(m.group(3), 16)
        for pc in [0x2f4b20, 0x2f4c84]:
            if addr_str <= pc < addr_str + size_str:
                print(f"0x{pc:x} is in section {name} (0x{addr_str:x}-0x{addr_str+size_str:x})")
